package project.init.account.utils;import org.passay.CharacterRule;import org.passay.EnglishCharacterData;import org.passay.PasswordGenerator;import java.util.Arrays;public class Utils {    public static String generateRandomText(int length) {        PasswordGenerator generator = new PasswordGenerator();        return generator.generatePassword(length, Arrays.asList(                new CharacterRule(EnglishCharacterData.UpperCase, 2),                new CharacterRule(EnglishCharacterData.LowerCase, 2),                new CharacterRule(EnglishCharacterData.Digit, 2)        ));    }}